const CATEGORIES = [["Figures", "Collectible figures and miniatures.", "figures"], ["Objects", "Decor, accessories and useful forms.", "objects"], ["3D Models", "STL, OBJ and 3MF ready to print.", "models"], ["Custom", "A production partner for your idea.", "custom"]];
const STORAGE = "formix-cart-v1";
const WISHLIST_STORAGE = "formix-wishlist-v1";
let cart = loadCart();
let wishlist = loadWishlist();
function loadCart() { try { const data = JSON.parse(localStorage.getItem(STORAGE) || "[]"); return Array.isArray(data) ? data.filter((x) => x && typeof x.id === "string" && Number(x.qty) > 0).map((x) => ({ id: x.id, qty: Math.floor(Number(x.qty)) })) : []; } catch { return []; } }
function saveCart() { localStorage.setItem(STORAGE, JSON.stringify(cart)); renderBadge(); }
function allProducts() { return [...OBJECTS, ...MODELS]; }
function findProduct(id) { return allProducts().find((p) => p.id === id); }
function money(value) { return new Intl.NumberFormat("ru-RU", { style: "currency", currency: "RUB", maximumFractionDigits: 0 }).format(value); }
function cartCount() { return cart.reduce((sum, line) => sum + line.qty, 0); }
function cartTotal() { return cart.reduce((sum, line) => { const product = findProduct(line.id); return sum + (product ? product.price * line.qty : 0); }, 0); }
function addToCart(id, qty = 1) { const line = cart.find((x) => x.id === id); if (line) line.qty += qty; else cart.push({ id, qty }); saveCart(); }
function loadWishlist() { try { const data = JSON.parse(localStorage.getItem(WISHLIST_STORAGE) || "[]"); return Array.isArray(data) ? data.filter((id) => typeof id === "string") : []; } catch { return []; } }
function toggleWishlist(id) { wishlist = wishlist.includes(id) ? wishlist.filter((item) => item !== id) : [...wishlist, id]; localStorage.setItem(WISHLIST_STORAGE, JSON.stringify(wishlist)); }
const PATHS = { samurai: "M50 8 64 25l-4 12 14 11-5 23-19 15-19-15-5-23 14-11-4-12Z", dragon: "M18 66c8-25 21-40 42-48 4 11 16 17 27 12-7 14-5 26 5 37-16 3-28-4-38 8-10-5-21-7-36-9Z", orb: "M50 14a28 28 0 1 1 0 56 28 28 0 0 1 0-56Zm0 13a15 15 0 1 0 0 30 15 15 0 0 0 0-30Z", mask: "M23 25h54l-7 49-20 13-20-13Z", mech: "M27 23h18l5 10h7l5-10h18v19l-8 8v28H36V50l-9-8Z", totem: "M50 10 74 25v24L50 89 26 49V25Z", rune: "M50 12 79 29v34L50 88 21 63V29Z" };
function art(product, tall = false) { const height = tall ? 560 : 250; return `<svg viewBox="0 0 100 100" class="art ${tall ? "art-tall" : ""}" style="height:${height}px;--accent:${product.accent}" role="img" aria-label="${product.title}"><defs><radialGradient id="g-${product.id}"><stop stop-color="${product.accent}" stop-opacity=".4"/><stop offset="1" stop-color="#141414"/></radialGradient></defs><rect width="100" height="100" fill="url(#g-${product.id})"/><circle cx="82" cy="20" r="18" fill="${product.accent}" opacity=".12"/><path d="${PATHS[product.shape]}" fill="${product.accent}" opacity=".2"/><path d="${PATHS[product.shape]}" fill="none" stroke="${product.accent}" stroke-width="1.8"/></svg>`; }
function button(action, label, className = "button button-light") { return `<button class="${className}" data-action="${action}">${label}</button>`; }
function objectCard(p) { return `<article class="product-card"><a href="#/product/${p.id}">${art(p)}</a><div class="product-card-body"><div class="eyebrow">FORMIX / ${p.code} <span>${p.status}</span></div><h3>${p.title}</h3><p>${p.material} · ${p.size * 10} mm</p><div class="card-bottom"><strong>${money(p.price)}</strong><div class="card-buttons">${button(`wish:${p.id}`, wishlist.includes(p.id) ? "♥" : "♡", "icon-button")} ${button(`add:${p.id}`, "Add to cart")}</div></div></div></article>`; }
function modelCard(p) { return `<article class="product-card"><a href="#/model/${p.id}">${art(p)}</a><div class="product-card-body"><div class="eyebrow">FORMIX MODEL / ${p.code} <span>${p.category}</span></div><h3>${p.title}</h3><p>${p.formats}</p><div class="card-bottom"><strong>${money(p.price)}</strong><div class="card-buttons">${button(`wish:${p.id}`, wishlist.includes(p.id) ? "♥" : "♡", "icon-button")} ${button(`add:${p.id}`, "Buy model")}</div></div></div></article>`; }
function hero() { return `<section class="hero"><div class="hero-copy"><div class="eyebrow">FORMIX STUDIO <span>EST. 2026</span></div><h1>FORMING IDEAS<br><em>INTO OBJECTS.</em></h1><p>3D-printed figures, collectibles, custom objects and digital models.</p><div class="actions"><a class="button button-light" href="#/shop">Explore Collection</a><a class="button button-line" href="#/custom">Create Custom</a></div></div><div class="hero-visual">${art(OBJECTS[0], true)}<div class="hero-index">OBJECT / 001<br><span>CYBER SAMURAI</span></div></div></section>`; }
function home() { return `${hero()}<section class="section"><div class="section-label">01 / CATEGORIES</div><div class="category-grid">${CATEGORIES.map(([title, text, route], i) => `<a class="category-block" href="#/${route === "models" ? "models" : route === "custom" ? "custom" : "shop"}"><span>0${i + 1}</span><h2>${title}</h2><p>${text}</p><b>↗</b></a>`).join("")}</div></section><section class="section"><div class="section-heading"><div><div class="section-label">02 / COLLECTION</div><h2>SELECTED OBJECTS</h2></div><a class="text-link" href="#/shop">View all objects <span>→</span></a></div><div class="product-grid">${OBJECTS.slice(0, 3).map(objectCard).join("")}</div></section>${studioPreview()}<section class="split-feature"><div><div class="section-label">04 / FORMIX DIGITAL</div><h2>PREMIUM 3D MODELS<br><em>READY TO PRINT.</em></h2><p>Digital assets built with the same attention to proportion, topology and finish as our physical objects.</p><a class="text-link" href="#/models">Explore 3D models <span>→</span></a></div><div class="mini-grid">${MODELS.slice(0, 2).map(modelCard).join("")}</div></section><section class="cta-band"><div class="section-label">05 / FORMIX STUDIO</div><h2>HAVE AN IDEA?</h2><p>Tell us what you want to create.</p><a class="button button-light" href="#/custom">Start a project</a></section>${newsletter()}`; }
function studioPreview() { return `<section class="studio-preview"><div><div class="section-label">03 / FORMIX STUDIO</div><h2>FROM PIXELS<br><em>TO PHYSICAL.</em></h2><p>One studio, five deliberate steps. Every object starts as an idea and leaves as something you can hold.</p></div><div class="process-list">${["DESIGN", "PROTOTYPE", "PRINT", "FINISH", "OBJECT"].map((x, i) => `<div><b>0${i + 1}</b><span>${x}</span><small>${["Shape the first idea.", "Test scale and balance.", "Build the real thing.", "Refine every surface.", "Make it yours."][i]}</small></div>`).join("")}</div></section>`; }
function newsletter() { return `<section class="newsletter"><div><div class="section-label">SIGNAL / 001</div><h2>STAY IN THE LOOP</h2><p>New collections, digital drops and studio notes.</p></div><form data-form="newsletter"><input type="email" placeholder="Your email" aria-label="Your email" required><button class="button button-light">Subscribe</button></form></section>`; }
function shop() { const params = new URLSearchParams(location.hash.split("?")[1] || ""); const category = params.get("category") || "all"; const material = params.get("material") || "all"; const size = params.get("size") || "all"; const price = params.get("price") || "all"; const availability = params.get("availability") || "all"; const list = OBJECTS.filter((p) => (category === "all" || p.category.toLowerCase() === category) && (material === "all" || p.material.toLowerCase() === material) && (size === "all" || (size === "small" ? p.size < 10 : size === "medium" ? p.size >= 10 && p.size <= 20 : size === "large" ? p.size > 20 : true)) && (price === "all" || (price === "low" ? p.price < 40 : price === "mid" ? p.price >= 40 && p.price <= 60 : p.price > 60)) && (availability === "all" || p.status.toLowerCase().replaceAll(" ", "-") === availability)); const labels = { all: "Все", figures: "Фигурки", objects: "Объекты", decor: "Декор", accessories: "Аксессуары", collectibles: "Коллекционные" }; const filter = (name, value) => { const next = new URLSearchParams(params); if (value === "all") next.delete(name); else next.set(name, value); return `#/shop${next.toString() ? `?${next}` : ""}`; }; return `<section class="page-intro"><div class="section-label">ОБЪЕКТЫ FORMIX / МАГАЗИН</div><h1>ФИЗИЧЕСКИЕ<br><em>ОБЪЕКТЫ.</em></h1><p>Фигурки, функциональные формы и коллекционные предметы небольшими студийными сериями.</p></section><section class="listing"><div class="filter-row"><div class="filter-tabs">${Object.keys(labels).map((x) => `<a class="${category === x ? "active" : ""}" href="${filter("category", x)}">${labels[x]}</a>`).join("")}</div><span>${list.length} объектов</span></div><div class="filter-controls"><label>Материал<select data-filter="material"><option value="all">Все материалы</option><option value="resin" ${material === "resin" ? "selected" : ""}>Смола</option><option value="pla" ${material === "pla" ? "selected" : ""}>PLA</option><option value="petg" ${material === "petg" ? "selected" : ""}>PETG</option></select></label><label>Размер<select data-filter="size"><option value="all">Любой размер</option><option value="small" ${size === "small" ? "selected" : ""}>До 10 см</option><option value="medium" ${size === "medium" ? "selected" : ""}>10–20 см</option><option value="large" ${size === "large" ? "selected" : ""}>Более 20 см</option></select></label><label>Цена<select data-filter="price"><option value="all">Любая цена</option><option value="low" ${price === "low" ? "selected" : ""}>До $40</option><option value="mid" ${price === "mid" ? "selected" : ""}>$40–60</option><option value="high" ${price === "high" ? "selected" : ""}>Более $60</option></select></label><label>Наличие<select data-filter="availability"><option value="all">Любое наличие</option><option value="in-stock" ${availability === "in-stock" ? "selected" : ""}>В наличии</option><option value="made-to-order" ${availability === "made-to-order" ? "selected" : ""}>На заказ</option><option value="pre-order" ${availability === "pre-order" ? "selected" : ""}>Предзаказ</option></select></label></div><div class="product-grid">${list.length ? list.map(objectCard).join("") : `<div class="empty-state">По этим фильтрам объектов нет.</div>`}</div></section>`; }
function models() { const params = new URLSearchParams(location.hash.split("?")[1] || ""); const category = params.get("category") || "all"; const format = params.get("format") || "all"; const difficulty = params.get("difficulty") || "all"; const sort = params.get("sort") || "featured"; let list = MODELS.filter((p) => (category === "all" || p.category.toLowerCase() === category) && (format === "all" || p.formats.toLowerCase().includes(format)) && (difficulty === "all" || p.difficulty.toLowerCase() === difficulty)); if (sort === "low") list.sort((a, b) => a.price - b.price); if (sort === "high") list.sort((a, b) => b.price - a.price); const update = (name, value) => { const next = new URLSearchParams(params); if (value === "all" || value === "featured") next.delete(name); else next.set(name, value); return `#/models${next.toString() ? `?${next}` : ""}`; }; return `<section class="page-intro"><div class="section-label">FORMIX DIGITAL / 3D-МОДЕЛИ</div><h1>ФАЙЛЫ ДЛЯ<br><em>СОЗДАТЕЛЕЙ.</em></h1><p>Премиальные цифровые модели, подготовленные для вашего принтера и следующей идеи.</p></section><section class="listing"><div class="filter-row"><div class="filter-tabs"><a class="${category === "all" ? "active" : ""}" href="${update("category", "all")}">Все модели</a><a class="${category === "characters" ? "active" : ""}" href="${update("category", "characters")}">Персонажи</a><a class="${category === "miniatures" ? "active" : ""}" href="${update("category", "miniatures")}">Миниатюры</a><a class="${category === "sci-fi" ? "active" : ""}" href="${update("category", "sci-fi")}">Фантастика</a><a class="${category === "decor" ? "active" : ""}" href="${update("category", "decor")}">Декор</a></div><span>${list.length} моделей</span></div><div class="filter-controls model-filters"><label>Формат<select data-model-filter="format"><option value="all">Любой формат</option><option value="stl" ${format === "stl" ? "selected" : ""}>STL</option><option value="obj" ${format === "obj" ? "selected" : ""}>OBJ</option><option value="3mf" ${format === "3mf" ? "selected" : ""}>3MF</option></select></label><label>Сложность<select data-model-filter="difficulty"><option value="all">Любая</option><option value="easy" ${difficulty === "easy" ? "selected" : ""}>Лёгкая</option><option value="medium" ${difficulty === "medium" ? "selected" : ""}>Средняя</option><option value="advanced" ${difficulty === "advanced" ? "selected" : ""}>Продвинутая</option></select></label><label>Сортировка<select data-model-filter="sort"><option value="featured" ${sort === "featured" ? "selected" : ""}>Рекомендуемые</option><option value="low" ${sort === "low" ? "selected" : ""}>Сначала дешевле</option><option value="high" ${sort === "high" ? "selected" : ""}>Сначала дороже</option></select></label></div><div class="product-grid">${list.length ? list.map(modelCard).join("") : `<div class="empty-state">По этим фильтрам моделей нет.</div>`}</div></section>`; }
function productPage(id, digital = false) { const p = findProduct(id); if (!p) return notFound(); const tabs = digital ? { description: "Цифровой файл подготовлен для самостоятельной печати. В архиве есть версии для разных масштабов и рекомендации по поддержкам.", specifications: `Форматы: ${p.formats}. Сложность: ${p.difficulty}. Масштаб: 100–250 мм.`, materials: "Модель проверена для печати на фотополимерном принтере. Поддержки включены в набор.", shipping: "После подтверждения оплаты ссылка на скачивание появится в Telegram." } : { description: p.description, specifications: p.specs.join(" · "), materials: `Основной материал: премиальная ${p.material}. Финиш: ручная обработка.`, shipping: `Производство: ${p.size >= 20 ? "5–7" : "3–5"} дней. Доставка обсуждается при оформлении в Telegram.` }; return `<section class="detail-page"><div class="detail-media ${digital ? "model-viewer" : ""}">${art(p, true)}<div class="media-note">ПРЕВЬЮ / ЦИФРОВОЙ РЕНДЕР<br><span>АРХИВ FORMIX</span></div>${digital ? `<div class="viewer-controls"><button data-view="-1">←</button><span>360° ПРОСМОТР</span><button data-view="1">→</button></div>` : `<div class="gallery-strip"><button class="active" data-gallery="main">01</button><button data-gallery="detail">02</button><button data-gallery="process">03</button></div>`}</div><div class="detail-info"><div class="eyebrow">${digital ? "МОДЕЛЬ FORMIX" : "FORMIX / " + p.code}<span>${p.type || p.category}</span></div><h1>${p.title}</h1><p class="detail-lead">${p.description}</p><div class="price-line"><strong>${money(p.price)}</strong><span>${digital ? "Мгновенная загрузка" : p.status}</span></div><div class="spec-grid">${(digital ? [["Рекомендуемый принтер", "Смола"], ["Масштаб", "100–250 мм"], ["Поддержки", "Включены"], ["Файлы", p.formats]] : [["Материал", `Премиальная ${p.material}`], ["Высота", `${p.size * 10} мм`], ["Отделка", "Ручная обработка"], ["Производство", "3–5 дней"]]).map(([a, b]) => `<div><span>${a}</span><b>${b}</b></div>`).join("")}</div>${button(`wish:${p.id}`, wishlist.includes(p.id) ? "♥ В избранном" : "♡ В избранное", "button button-line button-wide")}${button(`add:${p.id}`, digital ? "Купить и скачать" : "Добавить в корзину", "button button-light button-wide")}<a class="button button-line button-wide" href="#/custom">Заказать кастомную отделку</a><div class="info-tabs" role="tablist">${[["description", "Описание"], ["specifications", "Характеристики"], ["materials", "Материалы"], ["shipping", "Доставка"]].map(([key, label], index) => `<button class="${index === 0 ? "active" : ""}" data-tab="${key}" role="tab">${label}</button>`).join("")}</div><div class="tab-panel" data-tab-panel>${tabs.description}</div></div></section><section class="section related"><div class="section-heading"><div class="section-label">ПОХОЖИЕ ТОВАРЫ</div></div><div class="product-grid">${(digital ? MODELS : OBJECTS).filter((x) => x.id !== p.id).slice(0, 3).map(digital ? modelCard : objectCard).join("")}</div></section>`; }
function collections() { const items = [["001", "CYBER", "Sharp silhouettes, synthetic light and objects from a near future."], ["002", "MYTH", "Ancient forms translated into a new material language."], ["003", "VOID", "Monolithic studies for quiet rooms and loud imaginations."], ["004", "ORIGIN", "The first marks in the FORMIX archive."]]; return `<section class="page-intro"><div class="section-label">FORMIX ARCHIVE / COLLECTIONS</div><h1>WORLDS<br><em>IN FORM.</em></h1><p>Thematic releases that connect physical objects, digital models and the ideas behind them.</p></section><section class="collection-grid">${items.map(([code, title, text], i) => `<a class="collection-card" href="#/collections/${title.toLowerCase()}"><span>FORMIX / ${code}</span><h2>${title}</h2><p>${text}</p><b>Explore ↗</b><i style="--tone:${["#d6ff42", "#ff785a", "#c991ff", "#82aaff"][i]}"></i></a>`).join("")}</section>`; }
function collection(id) { const title = (id || "cyber").toUpperCase(); return `<section class="collection-hero"><div class="section-label">FORMIX COLLECTION / ${title}</div><h1>FORMIX / ${title}</h1><p>A focused series of objects and digital forms exploring material, silhouette and the space between useful and collectible.</p></section><section class="section"><div class="section-heading"><div class="section-label">OBJECTS IN THIS COLLECTION</div></div><div class="product-grid">${OBJECTS.slice(0, 3).map(objectCard).join("")}</div></section>`; }
function custom() { return `<section class="custom-hero"><div class="section-label">FORMIX STUDIO / CUSTOM</div><h1>YOUR IDEA.<br><em>OUR PRODUCTION.</em></h1><p>From first sketch to finished object, we build the right path around your project.</p></section><section class="services">${[["01", "3D MODELING", "Create a custom digital model from a sketch, reference or just an idea."], ["02", "3D PRINTING", "Choose the material, scale and production route for a real-world object."], ["03", "FINISHING", "Sanding, priming, painting and assembly for a final object with presence."]].map(([n, t, d]) => `<div><span>${n}</span><h2>${t}</h2><p>${d}</p></div>`).join("")}</section><section class="form-layout"><div><div class="section-label">START A PROJECT</div><h2>REQUEST<br><em>A QUOTE.</em></h2><p>Share the useful details. We will come back with a clear next step.</p></div><form class="project-form" data-form="custom"><label>What do you need?<select name="need"><option>3D Model</option><option>3D Print</option><option>Model + Print</option><option>Painting</option></select></label><label>Upload reference<input type="file" name="reference" accept="image/*,.stl,.obj,.3mf"></label><label>Tell us about your project...<textarea name="description" rows="5" required></textarea></label><div class="form-row"><label>Width / Height / Depth<input name="size" placeholder="e.g. 180 / 120 / 80 mm"></label><label>Quantity<input type="number" name="quantity" value="1" min="1"></label></div><div class="form-row"><label>Material<select><option>Resin</option><option>PLA</option><option>PETG</option><option>Other</option></select></label><label>Finish<select><option>Raw</option><option>Sanded</option><option>Primed</option><option>Painted</option></select></label></div><label>Deadline<input type="date" name="deadline"></label><button class="button button-light">Request a quote</button><div class="form-message" aria-live="polite"></div></form></section>`; }
function studio() { return `<section class="page-intro"><div class="section-label">FORMIX STUDIO</div><h1>WE CREATE<br><em>PHYSICAL IDEAS.</em></h1><p>FORMIX is a 3D studio for objects that deserve to exist beyond the screen.</p></section><section class="manifesto"><h2>Digital ideas.<br>Physical objects.</h2><p>We combine design, additive manufacturing and finishing into one focused practice. Small runs, considered materials, no unnecessary distance between an idea and the thing it becomes.</p></section>${studioPreview()}`; }
function production() { return `<section class="page-intro"><div class="section-label">FORMIX PRODUCTION</div><h1>THE MAKING<br><em>OF AN OBJECT.</em></h1><p>Seven stages from first geometry to final quality control.</p></section><section class="production-list">${["3D DESIGN", "PROTOTYPING", "3D PRINTING", "POST-PROCESSING", "PAINTING", "QUALITY CONTROL", "FINAL OBJECT"].map((x, i) => `<div><b>0${i + 1}</b><h2>${x}</h2><p>${["We define the shape, scale and reason for the object.", "Early prints test balance, tolerances and touch.", "The chosen process turns a file into a physical form.", "Supports disappear. Surfaces become intentional.", "Color and finish bring the object its final voice.", "Every edge, joint and surface gets a final check.", "Packed, documented and ready to enter the world."][i]}</p></div>`).join("")}</section>`; }
function faq() { const groups = [["Заказы", ["Как оформить заказ?", "Сколько занимает производство?", "Можно ли заказать несколько экземпляров?"]], ["3D-печать", ["Какие материалы вы используете?", "Можно ли напечатать мою модель?", "Какой максимальный размер?"]], ["Цифровые модели", ["Какие форматы файлов входят в заказ?", "Можно ли продавать распечатанные объекты?", "Можно ли изменить модель?"]], ["Доставка", ["Есть ли международная доставка?", "Сколько стоит доставка?", "Сколько занимает доставка?"]]]; return `<section class="page-intro compact"><div class="section-label">FORMIX / FAQ</div><h1>ВОПРОСЫ,<br><em>ОТВЕТЫ.</em></h1></section><section class="faq-list">${groups.map(([title, questions]) => `<div><div class="section-label">${title}</div>${questions.map((q) => `<details><summary>${q}<span>+</span></summary><p>Расскажите о проекте или заказе, и мы дадим понятный практический ответ с учётом объекта, материала и места доставки.</p></details>`).join("")}</div>`).join("")}</section>`; }
function contact() { return `<section class="page-intro compact"><div class="section-label">FORMIX / CONTACT</div><h1>LET'S MAKE<br><em>CONTACT.</em></h1><p>For commissions, wholesale, collaborations or a good object-related question.</p></section><section class="contact-layout"><div class="contact-data"><span>FORMIX STUDIO</span><a href="mailto:hello@formix.studio">hello@formix.studio</a><a href="#/contact">Telegram ↗</a><a href="#/contact">Instagram ↗</a><a href="#/contact">TikTok ↗</a></div><form class="project-form" data-form="contact"><label>Name<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Subject<input name="subject"></label><label>Message<textarea name="message" rows="6" required></textarea></label><button class="button button-light">Send message</button><div class="form-message" aria-live="polite"></div></form></section>`; }
function cartPage() { return `<section class="page-intro compact"><div class="section-label">FORMIX / CART</div><h1>YOUR<br><em>OBJECTS.</em></h1></section><section class="cart-layout"><div>${cart.length ? cart.map((line) => { const p = findProduct(line.id); return p ? `<div class="cart-line"><div class="cart-thumb">${art(p)}</div><div><div class="eyebrow">${p.category}</div><h3>${p.title}</h3><p>${p.material || p.formats}</p><div class="quantity"><button data-action="qty:${p.id}:-1">−</button><span>${line.qty}</span><button data-action="qty:${p.id}:1">+</button><button data-action="remove:${p.id}">Remove</button></div></div><strong>${money(p.price * line.qty)}</strong></div>` : ""; }).join("") : `<div class="empty-state">Your cart is waiting for its first object.</div>`}</div>${cart.length ? `<aside class="summary"><div class="eyebrow">ORDER SUMMARY</div><div><span>Subtotal</span><strong>${money(cartTotal())}</strong></div><div><span>Shipping</span><strong>Calculated at checkout</strong></div><hr><div class="total"><span>Total</span><strong>${money(cartTotal())}</strong></div><a class="button button-light button-wide" href="#/checkout">Checkout</a></aside>` : ""}</section>`; }
function checkout() { const message = ["Здравствуйте! Хочу оформить заказ в FORMIX:", ...cart.map((line) => { const p = findProduct(line.id); return p ? `• ${p.title} × ${line.qty} — ${money(p.price * line.qty)}` : ""; }), `Итого: ${money(cartTotal())}`].join("\n"); const telegram = `https://t.me/formix_studio?text=${encodeURIComponent(message)}`; return `<section class="page-intro compact"><div class="section-label">FORMIX / ЗАКАЗ</div><h1>ДАВАЙТЕ НАЧНЁМ<br><em>ЭТО РЕАЛЬНЫМ.</em></h1><p>Корзина готова. Отправьте заказ FORMIX в Telegram, и мы подтвердим наличие, доставку и оплату.</p></section><section class="checkout-layout"><div class="telegram-order"><div class="section-label">ЗАКАЗ ЧЕРЕЗ TELEGRAM</div><h2>ОДНО СООБЩЕНИЕ<br><em>ЧТОБЫ НАЧАТЬ.</em></h2><p>Текст заказа уже собран из вашей корзины. Нажмите кнопку, и сообщение откроется в Telegram.</p><a class="button button-light button-wide" href="${telegram}" target="_blank" rel="noreferrer">Открыть заказ в Telegram ↗</a><a class="button button-line button-wide" href="#/cart">Вернуться в корзину</a></div><aside class="summary"><div class="eyebrow">ВАШ ЗАКАЗ</div>${cart.map((line) => { const p = findProduct(line.id); return p ? `<p>${p.title} × ${line.qty}<strong>${money(p.price * line.qty)}</strong></p>` : ""; }).join("")}<hr><div class="total"><span>Итого</span><strong>${money(cartTotal())}</strong></div></aside></section>`; }
function tracking(id) { return `<section class="page-intro compact"><div class="section-label">FORMIX / ORDER ${id || "10482"}</div><h1>ORDER<br><em>IN MOTION.</em></h1></section><section class="tracking">${["Order received", "Payment confirmed", "Production", "Quality Control", "Shipped", "Delivered"].map((x, i) => `<div class="${i < 3 ? "done" : ""}"><b>${i < 3 ? "✓" : "0" + (i + 1)}</b><span>${x}</span></div>`).join("")}</section>`; }
