function localize(root) { const visible = { "MINIATURES": "МИНИАТЮРЫ", "Miniatures": "Миниатюры", "DECOR": "ДЕКОР", "Decor": "Декор", "SCI-FI": "ФАНТАСТИКА", "Raw": "Без обработки", "CONTACT": "КОНТАКТЫ", "SEARCH": "ПОИСК", "FIND THE": "НАЙТИ", "YOU MAY ALSO LIKE": "ПОХОЖИЕ ТОВАРЫ", "BUY & DOWNLOAD": "КУПИТЬ И СКАЧАТЬ", "Buy & download": "Купить и скачать", "ORDER SUMMARY": "СОСТАВ ЗАКАЗА", "IN MOTION.": "В РАБОТЕ.", "Premium": "Премиальная", "Height": "Высота", "Days": "дней", "MATERIAL": "МАТЕРИАЛ", "FINISH": "ОТДЕЛКА", "Recommended printer": "Рекомендуемый принтер", "Scale": "Масштаб", "Supports": "Поддержки", "Included": "Включены", "Files": "Файлы", "Production": "Производство", "POST-PROCESSING": "ПОСТОБРАБОТКА", "QUALITY CONTROL": "КОНТРОЛЬ КАЧЕСТВА", "FINAL OBJECT": "ГОТОВЫЙ ОБЪЕКТ" }; const replace = (value) => [...Object.entries(RU), ...Object.entries(RU_EXTRA), ...Object.entries(visible)].sort((a, b) => b[0].length - a[0].length).reduce((text, [from, to]) => text.split(from).join(to), value); const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT); const nodes = []; while (walker.nextNode()) nodes.push(walker.currentNode); nodes.forEach((node) => { node.nodeValue = replace(node.nodeValue); }); root.querySelectorAll("input, textarea").forEach((field) => { if (field.placeholder) field.placeholder = replace(field.placeholder); }); }
function parseRoute() { const [path] = location.hash.replace(/^#\/?/, "").split("?"); const parts = path.split("/"); return { name: parts[0] || "home", id: parts[1] }; }
function renderBadge() { const badge = document.getElementById("badge"); if (badge) { badge.textContent = cartCount(); badge.classList.toggle("hidden", !cartCount()); } }
function applySettings() { const links = [["footer-telegram", settings.telegram], ["footer-instagram", settings.instagram], ["footer-tiktok", settings.tiktok]]; links.forEach(([id, href]) => { const link = document.getElementById(id); if (link) link.href = href; }); }
function render() { const r = parseRoute(); const views = { home, shop, models, collections, collection, custom, studio, production, faq, contact, cart: cartPage, checkout, search, admin }; const root = document.getElementById("app"); root.classList.remove("page-enter"); if (r.name === "product") root.innerHTML = productPage(r.id); else if (r.name === "model") root.innerHTML = productPage(r.id, true); else if (r.name === "order") root.innerHTML = tracking(r.id); else if (r.name === "collections" && r.id) root.innerHTML = collection(r.id); else root.innerHTML = (views[r.name] || notFound)(); localize(root); applySettings(); requestAnimationFrame(() => root.classList.add("page-enter")); renderBadge(); window.scrollTo(0, 0); }
document.getElementById("app").addEventListener("click", (event) => { const tab = event.target.closest("[data-tab]"); if (tab) { const tabs = document.querySelectorAll("[data-tab]"); tabs.forEach((item) => item.classList.toggle("active", item === tab)); const panel = document.querySelector("[data-tab-panel]"); const product = findProduct(parseRoute().id); if (panel && product) { const digital = parseRoute().name === "model"; const content = digital ? { description: "Цифровой файл подготовлен для самостоятельной печати. В архиве есть версии для разных масштабов и рекомендации по поддержкам.", specifications: `Форматы: ${product.formats}. Сложность: ${product.difficulty}. Масштаб: 100–250 мм.`, materials: "Модель проверена для печати на фотополимерном принтере. Поддержки включены в набор.", shipping: "После подтверждения оплаты ссылка на скачивание появится в Telegram." } : { description: product.description, specifications: product.specs.join(" · "), materials: `Основной материал: премиальная ${product.material}. Финиш: ручная обработка.`, shipping: `Производство: ${product.size >= 20 ? "5–7" : "3–5"} дней. Доставка обсуждается при оформлении в Telegram.` }; panel.textContent = content[tab.dataset.tab]; } return; } const gallery = event.target.closest("[data-gallery]"); if (gallery) { document.querySelectorAll("[data-gallery]").forEach((item) => item.classList.toggle("active", item === gallery)); const artImage = document.querySelector(".detail-media .art"); if (artImage) artImage.style.filter = gallery.dataset.gallery === "detail" ? "saturate(1.5) contrast(1.15)" : gallery.dataset.gallery === "process" ? "sepia(.25) saturate(1.4)" : ""; return; } const view = event.target.closest("[data-view]"); if (view) { const artImage = document.querySelector(".model-viewer .art"); if (artImage) { const current = Number(artImage.dataset.rotation || 0) + Number(view.dataset.view) * 12; artImage.dataset.rotation = current; artImage.style.transform = `rotateY(${current}deg) scale(1.03)`; } return; } const target = event.target.closest("[data-action]"); if (!target) return; const [action, id, amount] = target.dataset.action.split(":"); if (action === "wish") { toggleWishlist(id); render(); return; } if (action === "add") { addToCart(id); location.hash = "/cart"; } if (action === "qty") { const line = cart.find((x) => x.id === id); if (line) line.qty = Math.max(1, line.qty + Number(amount)); saveCart(); render(); } if (action === "remove") { cart = cart.filter((x) => x.id !== id); saveCart(); render(); } if (action === "admin-logout") { adminAuthorized = false; sessionStorage.removeItem("formix-admin"); render(); } if (action === "admin-section") { target.classList.toggle("selected"); } });
document.getElementById("app").addEventListener("change", (event) => { const filter = event.target.closest("[data-filter]"); if (!filter) return; const params = new URLSearchParams(location.hash.split("?")[1] || ""); if (filter.value === "all") params.delete(filter.dataset.filter); else params.set(filter.dataset.filter, filter.value); location.hash = `/shop${params.toString() ? `?${params}` : ""}`; });
document.getElementById("app").addEventListener("submit", (event) => { const form = event.target; if (form.classList.contains("search-form")) { event.preventDefault(); location.hash = `/search?q=${encodeURIComponent(new FormData(form).get("q") || "")}`; return; } if (!form.dataset.form) return; event.preventDefault(); const message = form.querySelector(".form-message"); if (form.dataset.form === "admin-login") { const data = new FormData(form); if (data.get("login") === ADMIN_LOGIN && data.get("password") === ADMIN_PASSWORD) { adminAuthorized = true; sessionStorage.setItem("formix-admin", "ok"); render(); } else if (message) message.textContent = "Неверный логин или пароль."; return; } if (form.dataset.form === "checkout") { cart = []; saveCart(); location.hash = "/order/10482"; return; } if (form.dataset.form === "newsletter") form.reset(); if (message) message.textContent = form.dataset.form === "custom" ? "Заявка получена. Мы скоро свяжемся с вами." : "Вы подписаны на новости FORMIX."; });
window.addEventListener("hashchange", render); if (!location.hash) location.hash = "/"; render();
window.addEventListener("pointermove", (event) => { const x = (event.clientX / window.innerWidth - 0.5) * 28; const y = (event.clientY / window.innerHeight - 0.5) * 20; document.documentElement.style.setProperty("--mx", `${x}px`); document.documentElement.style.setProperty("--my", `${y}px`); });
window.addEventListener("keydown", (event) => { if (event.ctrlKey && event.shiftKey && event.key.toLowerCase() === "a") { event.preventDefault(); location.hash = "/admin"; } if ((event.ctrlKey || event.metaKey) && ["u", "s"].includes(event.key.toLowerCase())) event.preventDefault(); });
document.addEventListener("contextmenu", (event) => event.preventDefault());